contracts/MotherContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.25;

import "./RegistrarStorageUtil.sol";
import "./IUnifiedIdResolver.sol";
import "./SignatureVerifier.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";

/**
 * @title RegistrarStorageMother
 * @author kunalmkv
 * @notice Core contract for managing unified IDs across multiple blockchains
 * @dev Optimized version with enum errors and gas optimizations
 */
contract RegistrarStorageMother is Initializable, UUPSUpgradeable, PausableUpgradeable, AccessControlUpgradeable,ReentrancyGuardUpgradeable {
    using SignatureVerifier for bytes32;
    using SafeERC20 for IERC20;

    // === ERROR ENUMS FOR GAS OPTIMIZATION ===
    error E1(); // "Ownable: caller is not the owner"
    error E2(); // "Ownable: new owner is the zero address"
    error E3(); // "Ownable2Step: caller is not the new owner"
    error E4(); // "UnifiedID does not exist"
    error E5(); // "Contract is Paused"
    error E6(); // "UnifiedID already exists"
    error E7(); // "UnifiedID not available"
    error E8(); // "Caller not a registrar"
    error E9(); // "Caller not authorized relayer"
    error E10(); // "Caller not admin or owner"
    error E11(); // "Contract in emergency mode"
    error E12(); // "Util implementation: zero address"
    error E13(); // "Resolver: zero address"
    error E14(); // "Chain data does not exist"
    error E15(); // "Chain data already exists"
    error E16(); // "Maximum chains per unified ID reached"
    error E17(); // "Cannot add primary address as secondary"
    error E18(); // "Secondary address already exists"
    error E19(); // "Maximum secondary addresses per chain reached"
    error E20(); // "Old UnifiedID does not exist"
    error E21(); // "New UnifiedID already exists"
    error E22(); // "Too many secondary addresses"
    error E23(); // "Invalid signature"
    error E24(); // "Max chains must be greater than 0"
    error E25(); // "User cannot be zero address"
    error E26(); // "Cannot withdraw to zero address"
    error E27(); // "Insufficient balance"
    error E28(); // "ETH transfer failed"
    error E29(); // "Invalid token address"
    error E30(); // "ERC20 transfer failed"
    error E31(); // "Cannot update to same UnifiedId"
    error E32(); // "Cannot set same primary address"
    error E33(); // "Cannot set zero address as primary"

    // ==================== ROLE DEFINITIONS ====================

    /// @notice Role for authorized relayers who can execute operations
    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");

    /// @notice Role for admin users with elevated privileges
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Role for emergency operations
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");

    /// @notice Role for upgrading the contract
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    // === STORAGE VARIABLES ===
    RegistrarStorageUtil public util;
    IUnifiedIdResolver public resolver;

    // Ownable2Step implementation
    address private _owner;
    address private _pendingOwner;

    // Core storage structures
    struct ChainData {
        address primary;
        address[] secondaries;
        bool exists;
    }

    struct UnifiedID {
        address masterAddress;
        mapping(uint256 => ChainData) chains;
        uint256[] registeredChainIds;
        bool exists;
    }

    mapping(string => UnifiedID) private unifiedIds;
    mapping(string => bool) public isUnavailableUnifiedId;
    mapping(string => uint256) public nonces;

    // Packed configuration struct for gas optimization
    struct PackedConfig {
        uint128 maxSecondaryAddressesPerChain;
        uint128 maxChainsPerUnifiedId;
        bool emergencyMode;
    }

    PackedConfig public config;

    // EIP-712 constants
    bytes32 public constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );

    bytes32 public constant REGISTER_TYPEHASH = keccak256(
        "RegisterUnifiedId(string unifiedId,address primary,uint256 chainId,uint256 nonce)"
    );

    bytes32 public DOMAIN_SEPARATOR;

    // === EVENTS ===
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event MaxSecondaryAddressesPerChainUpdated(uint256 oldMax, uint256 newMax);
    event MaxChainsPerUnifiedIdUpdated(uint256 oldMax, uint256 newMax);
    event EmergencyModeToggled(bool enabled);
    event ResolverUpdated(address indexed oldResolver, address indexed newResolver, address indexed updatedBy);
    event ContractPaused(address indexed pausedBy, uint256 timestamp);
    event ContractUnpaused(address indexed unpausedBy, uint256 timestamp);
    event RelayerAuthorizationUpdated(address indexed relayer, bool authorized);
    event UpgradeAuthorized(address indexed newImplementation, address indexed authorizedBy, uint256 timestamp);
    event EmergencyUnifiedIdMarked(string indexed unifiedId, bool available, address indexed updatedBy);
    event EmergencyChainDataCleared(string indexed unifiedId, uint256 indexed chainId, address indexed clearedBy);
    event UnifiedIdRegistered(string indexed unifiedId, address indexed masterAddress, uint256 indexed chainId, address primary);
    event UnifiedIdUpdated(string indexed newUnifiedId, string indexed oldUnifiedId);
    event MasterAddressUpdated(string indexed unifiedId, address indexed newMasterAddress);
    event PrimaryAddressUpdated(string indexed unifiedId, uint256 indexed chainId, address indexed newPrimary);
    event SecondaryAddressAdded(string indexed unifiedId, uint256 indexed chainId, address indexed secondary);
    event SecondaryAddressRemoved(string indexed unifiedId, uint256 indexed chainId, address indexed secondary);
    event EthWithdrawn(address indexed to, uint256 amount);
    event ERC20Withdrawn(address indexed token, address indexed to, uint256 amount);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // === MODIFIERS ===
    modifier onlyOwner() {
        if (owner() != msg.sender) revert E1();
        _;
    }

    modifier onlyAdmin() {
        require(hasRole(ADMIN_ROLE, msg.sender) || msg.sender == owner(), "AccessControl: caller is not admin");
        _;
    }

    modifier notInEmergencyMode() {
        if (config.emergencyMode) revert E11();
        _;
    }

    modifier onlyRelayer() {
        require(hasRole(RELAYER_ROLE, msg.sender), "AccessControl: caller is not relayer");
        _;
    }

    // === OWNABLE2STEP IMPLEMENTATION ===
    function owner() public view virtual returns (address) {
        return _owner;
    }

    function pendingOwner() public view virtual returns (address) {
        return _pendingOwner;
    }

    function renounceOwnership() public virtual onlyOwner {
        _transferOwnership(address(0));
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        if (newOwner == address(0)) revert E2();
        _pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner(), newOwner);
    }

    function acceptOwnership() external {
        address sender = msg.sender;
        if (pendingOwner() != sender) revert E3();
        _transferOwnership(sender);
    }

    function _transferOwnership(address newOwner) internal virtual {
        delete _pendingOwner;
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    // === INITIALIZATION ===
    function initialize(address _util, address _resolver) public initializer {
        if (_util == address(0)) revert E12();
        if (_resolver == address(0)) revert E13();

        __UUPSUpgradeable_init();
        __Pausable_init();
        __AccessControl_init();

        // Initialize EIP-712 domain separator with proxy address
        DOMAIN_SEPARATOR = SignatureVerifier.createDomainSeparator(
            SignatureVerifier.DomainData({
                name: "UnifiedID",
                version: "1",
                chainId: block.chainid,
                verifyingContract: address(this)
            })
        );

        // Initialize ownership
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);

        util = RegistrarStorageUtil(_util);
        resolver = IUnifiedIdResolver(_resolver);

        // Initialize packed config
        config = PackedConfig({
            maxSecondaryAddressesPerChain: 10,
            maxChainsPerUnifiedId: 50,
            emergencyMode: false
        });

        // Setup roles
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(EMERGENCY_ROLE, msg.sender);
        _grantRole(UPGRADER_ROLE, msg.sender);
    }

    // === CORE FUNCTIONS ===
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
        emit ContractPaused(msg.sender, block.timestamp);
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
        emit ContractUnpaused(msg.sender, block.timestamp);
    }

    function setResolver(address _resolver) external onlyRole(ADMIN_ROLE) {
        if (_resolver == address(0)) revert E13();
        address oldResolver = address(resolver);
        resolver = IUnifiedIdResolver(_resolver);
        emit ResolverUpdated(oldResolver, _resolver, msg.sender);
    }

    function _authorizeUpgrade(address newImplementation) internal override {
        require(hasRole(UPGRADER_ROLE, msg.sender) || msg.sender == owner(), "AccessControl: caller is not upgrader");
        emit UpgradeAuthorized(newImplementation, msg.sender, block.timestamp);
    }

    function registerUnifiedId(
        string calldata unifiedId,
        uint256 chainId,
        address primary,
        SignatureVerifier.SignatureData calldata masterSigData,
        SignatureVerifier.SignatureData calldata primarySigData
    ) external onlyRelayer whenNotPaused notInEmergencyMode {
        if (isUnavailableUnifiedId[unifiedId]) revert E7();

        UnifiedID storage uid = unifiedIds[unifiedId];
        ChainData storage chainData = uid.chains[chainId];

        if (chainData.exists) revert E15();
        if (uid.registeredChainIds.length >= config.maxChainsPerUnifiedId) revert E16();

        // Verify primary signature
        if (!SignatureVerifier.verifyRegisterSignature(
            DOMAIN_SEPARATOR,
            unifiedId,
            primary,
            primary,
            primarySigData
        )) revert E23();

        // Update nonce
        if (primarySigData.nonce != nonces[unifiedId]) revert E23();
        nonces[unifiedId]++;

        if (!uid.exists) {
            // New UnifiedID
            uid.masterAddress = primary;
            uid.exists = true;
        } else {
            // Existing UnifiedID - verify master signature
            if (!SignatureVerifier.verifyRegisterSignature(
                DOMAIN_SEPARATOR,
                unifiedId,
                primary,
                uid.masterAddress,
                masterSigData
            )) revert E23();
        }

        chainData.primary = primary;
        chainData.exists = true;
        uid.registeredChainIds.push(chainId);

        // Update resolver
        resolver.setUnifiedIdPrimaryAddress(unifiedId, chainId, primary);

        emit UnifiedIdRegistered(unifiedId, uid.masterAddress, chainId, primary);
    }

    function updatePrimaryAddress(
        string calldata unifiedId,
        uint256 chainId,
        address newPrimary,
        SignatureVerifier.SignatureData calldata currentSigData,
        SignatureVerifier.SignatureData calldata newSigData
    ) external onlyRelayer whenNotPaused {
        if (!unifiedIds[unifiedId].exists) revert E4();
        if (!unifiedIds[unifiedId].chains[chainId].exists) revert E14();

        address currentPrimary = unifiedIds[unifiedId].chains[chainId].primary;

        // EDGE CASE PROTECTION: Prevent setting the same primary address
        if (currentPrimary == newPrimary) revert E32();

        // EDGE CASE PROTECTION: Prevent setting zero address as primary
        if (newPrimary == address(0)) revert E33();

        // Verify both signatures
        if (!SignatureVerifier.verifyUpdatePrimarySignature(
            DOMAIN_SEPARATOR,
            unifiedId,
            newPrimary,
            currentPrimary,
            currentSigData
        )) revert E23();

        if (!SignatureVerifier.verifyUpdatePrimarySignature(
            DOMAIN_SEPARATOR,
            unifiedId,
            newPrimary,
            newPrimary,
            newSigData
        )) revert E23();

        // Update nonce
        if (currentSigData.nonce != nonces[unifiedId]) revert E23();
        nonces[unifiedId]++;

        unifiedIds[unifiedId].chains[chainId].primary = newPrimary;

        // Update resolver
        resolver.updateUnifiedIdPrimaryAddress(unifiedId, chainId, newPrimary);

        emit PrimaryAddressUpdated(unifiedId, chainId, newPrimary);
    }

    function addSecondaryAddress(
        string calldata unifiedId,
        uint256 chainId,
        address secondary,
        SignatureVerifier.SignatureData calldata primarySigData,
        SignatureVerifier.SignatureData calldata secondarySigData
    ) external onlyRelayer whenNotPaused {
        if (!unifiedIds[unifiedId].exists) revert E4();
        if (!unifiedIds[unifiedId].chains[chainId].exists) revert E14();

        address primary = unifiedIds[unifiedId].chains[chainId].primary;

        if (primary == secondary) revert E17();

        ChainData storage chainData = unifiedIds[unifiedId].chains[chainId];
        if (chainData.secondaries.length >= config.maxSecondaryAddressesPerChain) revert E19();

        // Check for duplicates
        for (uint256 i = 0; i < chainData.secondaries.length; ++i) {
            if (chainData.secondaries[i] == secondary) revert E18();
        }

        // Verify signatures
        if (!SignatureVerifier.verifyAddSecondarySignature(
            DOMAIN_SEPARATOR,
            unifiedId,
            secondary,
            primary,
            primarySigData
        )) revert E23();

        if (!SignatureVerifier.verifyAddSecondarySignature(
            DOMAIN_SEPARATOR,
            unifiedId,
            secondary,
            secondary,
            secondarySigData
        )) revert E23();

        // Update nonce
        if (primarySigData.nonce != nonces[unifiedId]) revert E23();
        nonces[unifiedId]++;

        chainData.secondaries.push(secondary);

        // Update resolver
        resolver.addUnifiedIdSecondaryAddress(unifiedId, chainId, secondary);

        emit SecondaryAddressAdded(unifiedId, chainId, secondary);
    }

    function removeSecondaryAddress(
        string calldata unifiedId,
        uint256 chainId,
        address secondary,
        SignatureVerifier.SignatureData calldata sigData
    ) external onlyRelayer whenNotPaused {
        if (!unifiedIds[unifiedId].exists) revert E4();
        if (!unifiedIds[unifiedId].chains[chainId].exists) revert E14();

        address primary = unifiedIds[unifiedId].chains[chainId].primary;

        // Verify signature
        if (!SignatureVerifier.verifyRemoveSecondarySignature(
            DOMAIN_SEPARATOR,
            unifiedId,
            secondary,
            primary,
            sigData
        )) revert E23();

        // Update nonce
        if (sigData.nonce != nonces[unifiedId]) revert E23();
        nonces[unifiedId]++;

        ChainData storage chainData = unifiedIds[unifiedId].chains[chainId];

        if (chainData.secondaries.length > config.maxSecondaryAddressesPerChain) revert E22();

        for (uint256 i = 0; i < chainData.secondaries.length; ++i) {
            if (chainData.secondaries[i] == secondary) {
                chainData.secondaries[i] = chainData.secondaries[chainData.secondaries.length - 1];
                chainData.secondaries.pop();

                // Update resolver
                resolver.removeUnifiedIdSecondaryAddress(unifiedId, chainId, secondary);

                emit SecondaryAddressRemoved(unifiedId, chainId, secondary);
                break;
            }
        }
    }

    function updateUnifiedId(
        string calldata oldUnifiedId,
        string calldata newUnifiedId,
        SignatureVerifier.SignatureData calldata sigData
    ) external onlyRelayer whenNotPaused {
        if (isUnavailableUnifiedId[oldUnifiedId]) revert E7();
        if (isUnavailableUnifiedId[newUnifiedId]) revert E7();
        if (!unifiedIds[oldUnifiedId].exists) revert E20();
        if (unifiedIds[newUnifiedId].exists) revert E21();

        // EDGE CASE PROTECTION: Prevent updating to the same UnifiedId
        if (keccak256(bytes(oldUnifiedId)) == keccak256(bytes(newUnifiedId))) revert E31();

        address masterAddress = unifiedIds[oldUnifiedId].masterAddress;

        // Verify signature
        if (!SignatureVerifier.verifyUpdateUnifiedIdSignature(
            DOMAIN_SEPARATOR,
            oldUnifiedId,
            newUnifiedId,
            masterAddress,
            sigData
        )) revert E23();

        // Update nonce
        if (sigData.nonce != nonces[oldUnifiedId]) revert E23();
        nonces[newUnifiedId] = nonces[oldUnifiedId] + 1;
        delete nonces[oldUnifiedId];

        _transferUnifiedIdData(oldUnifiedId, newUnifiedId);
        _cleanupOldUnifiedId(oldUnifiedId, newUnifiedId);
    }

    function _transferUnifiedIdData(string memory oldUnifiedId, string memory newUnifiedId) internal {
        UnifiedID storage existing = unifiedIds[oldUnifiedId];
        uint256[] memory chainIds = existing.registeredChainIds;

        UnifiedID storage updated = unifiedIds[newUnifiedId];
        updated.masterAddress = existing.masterAddress;
        updated.exists = true;

        for (uint256 i = 0; i < chainIds.length; ++i) {
            uint256 cid = chainIds[i];
            ChainData storage existingChain = existing.chains[cid];
            ChainData storage newChain = updated.chains[cid];

            newChain.primary = existingChain.primary;
            newChain.exists = existingChain.exists;

            uint256 maxSecondaryIterations = existingChain.secondaries.length > config.maxSecondaryAddressesPerChain ?
                uint256(config.maxSecondaryAddressesPerChain) : existingChain.secondaries.length;

            for (uint256 j = 0; j < maxSecondaryIterations;) {
                newChain.secondaries.push(existingChain.secondaries[j]);
                unchecked { ++j; }
            }

            updated.registeredChainIds.push(cid);

            _updateResolverForNewUnifiedId(newUnifiedId, cid, newChain);

            unchecked { ++i; }
        }
    }

    function _updateResolverForNewUnifiedId(string memory newUnifiedId, uint256 chainId, ChainData storage chainData) internal {
        if (chainData.primary != address(0)) {
            resolver.setUnifiedIdPrimaryAddress(newUnifiedId, chainId, chainData.primary);

            address[] storage secondaries = chainData.secondaries;

            uint256 maxSecondaryIterations = secondaries.length > config.maxSecondaryAddressesPerChain ?
                uint256(config.maxSecondaryAddressesPerChain) : secondaries.length;

            for (uint256 j; j < maxSecondaryIterations;) {
                resolver.addUnifiedIdSecondaryAddress(newUnifiedId, chainId, secondaries[j]);
                unchecked { ++j; }
            }
        }
    }

    function _cleanupOldUnifiedId(string memory oldUnifiedId, string memory newUnifiedId) internal {
        uint256[] memory chainIds = unifiedIds[oldUnifiedId].registeredChainIds;

        uint256 maxIterations = chainIds.length > config.maxChainsPerUnifiedId ?
            uint256(config.maxChainsPerUnifiedId) : chainIds.length;

        for (uint256 i; i < maxIterations;) {
            uint256 cid = chainIds[i];
            resolver.clearUnifiedIdMappings(oldUnifiedId, cid);
            delete unifiedIds[oldUnifiedId].chains[cid];
            unchecked { ++i; }
        }

        delete unifiedIds[oldUnifiedId];
        emit UnifiedIdUpdated(newUnifiedId, oldUnifiedId);
    }

    function updateMasterAddress(
        string calldata unifiedId,
        address newMasterAddress,
        SignatureVerifier.SignatureData calldata sigData
    ) external onlyRelayer whenNotPaused {
        if (!unifiedIds[unifiedId].exists) revert E4();

        address currentMasterAddress = unifiedIds[unifiedId].masterAddress;

        // Verify signature
        if (!SignatureVerifier.verifyUpdateMasterSignature(
            DOMAIN_SEPARATOR,
            unifiedId,
            newMasterAddress,
            currentMasterAddress,
            sigData
        )) revert E23();

        // Update nonce
        if (sigData.nonce != nonces[unifiedId]) revert E23();
        nonces[unifiedId]++;

        unifiedIds[unifiedId].masterAddress = newMasterAddress;

        emit MasterAddressUpdated(unifiedId, newMasterAddress);
    }

    // === VIEW FUNCTIONS ===
    function getMasterAddress(string calldata unifiedId) external view returns (address) {
        return unifiedIds[unifiedId].masterAddress;
    }

    function getChainData(
        string calldata unifiedId,
        uint256 chainId
    ) external view returns (address primary, address[] memory secondaries) {
        ChainData storage chainData = unifiedIds[unifiedId].chains[chainId];
        return (chainData.primary, chainData.secondaries);
    }

    function getNonce(string calldata unifiedId) external view returns (uint256) {
        return nonces[unifiedId];
    }

    function isChainRegistered(string calldata unifiedId, uint256 chainId) external view returns (bool) {
        uint256[] memory chainIds = unifiedIds[unifiedId].registeredChainIds;

        uint256 maxIterations = chainIds.length > config.maxChainsPerUnifiedId ?
            uint256(config.maxChainsPerUnifiedId) : chainIds.length;

        for (uint256 i; i < maxIterations;) {
            if (chainIds[i] == chainId) {
                return true;
            }
            unchecked { ++i; }
        }
        return false;
    }

    function getRegisteredChainIds(string calldata unifiedId) external view returns (uint256[] memory) {
        return unifiedIds[unifiedId].registeredChainIds;
    }

    function resolveAddressToUnifiedId(address addr, uint256 chainId) external view returns (string memory) {
        return resolver.getUnifiedIdFromAddress(addr, chainId);
    }

    function resolvePrimaryAddress(string calldata unifiedId, uint256 chainId) external view returns (address) {
        return resolver.getPrimaryAddress(unifiedId, chainId);
    }

    function resolveAllAddresses(string calldata unifiedId, uint256 chainId)
    external view returns (address primary, address[] memory secondaries) {
        return resolver.getAddresses(unifiedId, chainId);
    }

    // ==================== COMBINED ADDRESS FUNCTIONS ====================

    /**
     * @notice Gets all addresses (primary + secondary) for a UnifiedId in a single array on specific chain
     * @dev Returns all addresses associated with the UnifiedId on the specified chain in one array
     * @param unifiedId The UnifiedId to get all addresses for
     * @param chainId The chain ID to query
     * @return allAddresses Array containing primary address followed by all secondary addresses
     * @custom:gas-optimization Efficient single-call solution instead of multiple calls + concatenation
     * @custom:use-cases
     * - DApp integration for displaying all addresses
     * - Wallet interfaces showing complete address list
     * - Permission checking across all addresses
     * - Simplified iteration over all addresses
     * @custom:array-structure [primary, secondary1, secondary2, ...]
     */
    function getAllAddresses(string calldata unifiedId, uint256 chainId) external view returns (address[] memory allAddresses) {
        return resolver.getAllAddresses(unifiedId, chainId);
    }

    /**
     * @notice Gets the total count of addresses (primary + secondary) for a UnifiedId on specific chain
     * @dev Returns the total number of addresses associated with the UnifiedId on the specified chain
     * @param unifiedId The UnifiedId to count addresses for
     * @param chainId The chain ID to query
     * @return count Total number of addresses (1 primary + N secondary addresses)
     * @custom:gas-optimization Lightweight function for getting address count without array allocation
     * @custom:use-cases
     * - Pre-allocating arrays for address operations
     * - Checking if UnifiedId has multiple addresses
     * - Gas estimation for batch operations
     */
    function getAddressCount(string calldata unifiedId, uint256 chainId) external view returns (uint256 count) {
        return resolver.getAddressCount(unifiedId, chainId);
    }

    /**
     * @notice Checks if a UnifiedId has multiple addresses on a specific chain
     * @dev Convenience function to check if UnifiedId has secondary addresses on the specified chain
     * @param unifiedId The UnifiedId to check
     * @param chainId The chain ID to query
     * @return hasMultiple True if UnifiedId has secondary addresses in addition to primary
     * @custom:gas-optimization Uses address count instead of fetching full arrays
     */
    function hasMultipleAddresses(string calldata unifiedId, uint256 chainId) external view returns (bool hasMultiple) {
        return resolver.getAddressCount(unifiedId, chainId) > 1;
    }

    /**
     * @notice Gets all addresses across all registered chains for a UnifiedId
     * @dev Returns addresses from all chains where the UnifiedId is registered
     * @param unifiedId The UnifiedId to get addresses for
     * @return chainIds Array of chain IDs where UnifiedId is registered
     * @return allAddressesPerChain Array of address arrays, one per chain
     * @custom:gas-optimization Batches multi-chain queries in single call
     * @custom:multi-chain Comprehensive cross-chain address retrieval
     * @custom:use-cases
     * - Complete UnifiedId address overview
     * - Cross-chain DApp integration
     * - Multi-chain wallet displays
     */
    function getAllAddressesAcrossChains(string calldata unifiedId) external view returns (
        uint256[] memory chainIds,
        address[][] memory allAddressesPerChain
    ) {
        chainIds = unifiedIds[unifiedId].registeredChainIds;
        allAddressesPerChain = new address[][](chainIds.length);

        for (uint256 i = 0; i < chainIds.length; ++i) {
            allAddressesPerChain[i] = resolver.getAllAddresses(unifiedId, chainIds[i]);
        }

        return (chainIds, allAddressesPerChain);
    }

    // === ADMIN FUNCTIONS ===
    function setMaxSecondaryAddressesPerChain(uint256 _maxSecondaryAddresses) external onlyRole(ADMIN_ROLE) {
        uint256 oldMax = config.maxSecondaryAddressesPerChain;
        config.maxSecondaryAddressesPerChain = uint128(_maxSecondaryAddresses);
        emit MaxSecondaryAddressesPerChainUpdated(oldMax, _maxSecondaryAddresses);
    }

    function setMaxChainsPerUnifiedId(uint256 _maxChains) external onlyRole(ADMIN_ROLE) {
        if (_maxChains == 0) revert E24();
        uint256 oldMax = config.maxChainsPerUnifiedId;
        config.maxChainsPerUnifiedId = uint128(_maxChains);
        emit MaxChainsPerUnifiedIdUpdated(oldMax, _maxChains);
    }

    function setEmergencyMode(bool _enabled) external onlyRole(EMERGENCY_ROLE) {
        config.emergencyMode = _enabled;
        emit EmergencyModeToggled(_enabled);
    }

    function emergencyMarkUnavailable(string calldata _unifiedId) external onlyRole(EMERGENCY_ROLE) {
        isUnavailableUnifiedId[_unifiedId] = true;
        emit EmergencyUnifiedIdMarked(_unifiedId, false, msg.sender);
    }

    function emergencyMarkAvailable(string calldata _unifiedId) external onlyRole(EMERGENCY_ROLE) {
        isUnavailableUnifiedId[_unifiedId] = false;
        emit EmergencyUnifiedIdMarked(_unifiedId, true, msg.sender);
    }

    function emergencyCleanupChainData(string calldata _unifiedId, uint256 _chainId) external onlyRole(EMERGENCY_ROLE) {
        if (!unifiedIds[_unifiedId].exists) revert E4();
        if (!unifiedIds[_unifiedId].chains[_chainId].exists) revert E14();

        delete unifiedIds[_unifiedId].chains[_chainId];

        uint256[] storage chainIds = unifiedIds[_unifiedId].registeredChainIds;

        uint256 maxIterations = chainIds.length > config.maxChainsPerUnifiedId ?
            uint256(config.maxChainsPerUnifiedId) : chainIds.length;

        for (uint256 i; i < maxIterations;) {
            if (chainIds[i] == _chainId) {
                chainIds[i] = chainIds[chainIds.length - 1];
                chainIds.pop();
                break;
            }
            unchecked { ++i; }
        }

        emit EmergencyChainDataCleared(_unifiedId, _chainId, msg.sender);
    }

    function getConfiguration() external view returns (
        uint256 _maxSecondaryAddressesPerChain,
        uint256 _maxChainsPerUnifiedId,
        bool _emergencyMode
    ) {
        return (
            config.maxSecondaryAddressesPerChain,
            config.maxChainsPerUnifiedId,
            config.emergencyMode
        );
    }

    receive() external payable {}
    fallback() external payable {}

    /**
  * @notice Withdraws ETH from the contract to a specified address
 * @param to The address to send ETH to
 * @param amount The amount of ETH to withdraw in wei
 */
    function withdrawEth(address payable to, uint256 amount) external onlyOwner nonReentrant {
        require(to != address(0), "Invalid recipient address");
        require(amount > 0, "Amount must be greater than 0");
        require(amount <= address(this).balance, "Insufficient contract balance");

        // Emit event before external call (CEI pattern)
        emit EthWithdrawn(to, amount);

        // Transfer with limited gas to prevent griefing
        (bool success, ) = to.call{value: amount, gas: 50000}("");
        require(success, "ETH transfer failed");
    }
/**
 * @notice Withdraws ERC20 tokens from the contract to a specified address
 * @param token The ERC20 token contract address
 * @param to The address to send tokens to
 * @param amount The amount of tokens to withdraw (in token's smallest unit)
 */
    function withdrawERC20(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        // Validations
        require(token != address(0), "Invalid token address");
        require(to != address(0), "Invalid recipient address");
        require(amount > 0, "Amount must be greater than 0");

        // Verify token is a contract
        uint256 codeSize;
        assembly { codeSize := extcodesize(token) }
        require(codeSize > 0, "Token address is not a contract");

        // Check current balance
        uint256 contractBalance = IERC20(token).balanceOf(address(this));
        require(contractBalance >= amount, "Insufficient token balance");

        // Get balance before transfer (for fee-on-transfer tokens)
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));

        // Use SafeERC20 for safe transfer
        IERC20(token).safeTransfer(to, amount);

        // Calculate actual transferred amount (handles fee-on-transfer tokens)
        uint256 balanceAfter = IERC20(token).balanceOf(address(this));
        uint256 actualTransferred = balanceBefore - balanceAfter;

        // Emit event with actual transferred amount
        emit ERC20Withdrawn(token, to, actualTransferred);
    }

    // ==================== ROLE MANAGEMENT FUNCTIONS ====================

    /**
     * @notice Grant relayer role to an address
     * @param relayer Address to grant relayer role
     */
    function grantRelayerRole(address relayer) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(RELAYER_ROLE, relayer);
        emit RelayerAuthorizationUpdated(relayer, true);
    }

    /**
     * @notice Revoke relayer role from an address
     * @param relayer Address to revoke relayer role
     */
    function revokeRelayerRole(address relayer) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(RELAYER_ROLE, relayer);
        emit RelayerAuthorizationUpdated(relayer, false);
    }

    /**
     * @notice Grant admin role to an address
     * @param admin Address to grant admin role
     */
    function grantAdminRole(address admin) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(ADMIN_ROLE, admin);
    }

    /**
     * @notice Revoke admin role from an address
     * @param admin Address to revoke admin role
     */
    function revokeAdminRole(address admin) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(ADMIN_ROLE, admin);
    }

    /**
     * @notice Grant emergency role to an address
     * @param emergency Address to grant emergency role
     */
    function grantEmergencyRole(address emergency) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(EMERGENCY_ROLE, emergency);
    }

    /**
     * @notice Revoke emergency role from an address
     * @param emergency Address to revoke emergency role
     */
    function revokeEmergencyRole(address emergency) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(EMERGENCY_ROLE, emergency);
    }

    /**
     * @notice Grant upgrader role to an address
     * @param upgrader Address to grant upgrader role
     */
    function grantUpgraderRole(address upgrader) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(UPGRADER_ROLE, upgrader);
    }

    /**
     * @notice Revoke upgrader role from an address
     * @param upgrader Address to revoke upgrader role
     */
    function revokeUpgraderRole(address upgrader) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(UPGRADER_ROLE, upgrader);
    }

    /**
     * @notice Check if address has relayer role
     * @param account Address to check
     * @return True if address has relayer role
     */
    function isRelayer(address account) external view returns (bool) {
        return hasRole(RELAYER_ROLE, account);
    }

    /**
     * @notice Check if address has admin role
     * @param account Address to check
     * @return True if address has admin role
     */
    function isAdmin(address account) external view returns (bool) {
        return hasRole(ADMIN_ROLE, account);
    }

    /**
     * @notice Check if address has emergency role
     * @param account Address to check
     * @return True if address has emergency role
     */
    function isEmergencyResponder(address account) external view returns (bool) {
        return hasRole(EMERGENCY_ROLE, account);
    }

    /**
     * @notice Check if address has upgrader role
     * @param account Address to check
     * @return True if address has upgrader role
     */
    function isUpgrader(address account) external view returns (bool) {
        return hasRole(UPGRADER_ROLE, account);
    }
}

contracts/RegistrarStorageChildEvents.so.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.25;

import "./RegistrarStorageUtil.sol";
import "./IUnifiedIdResolver.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";

/**
 * @title RegistrarStorageChildEvents
 * @author kunalmkv
 * @notice Chain-specific unified ID management contract
 * @dev Optimized version with enum errors and gas optimizations
 */
contract RegistrarStorageChildEvents is Initializable, UUPSUpgradeable, AccessControlUpgradeable {

    // ==================== ROLE DEFINITIONS ====================

    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");
    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    // === ERROR ENUMS FOR GAS OPTIMIZATION ===
    error E1(); error E2(); error E3(); error E4(); error E5(); error E6(); error E7(); error E8(); error E9(); error E10();
    error E11(); error E12(); error E13(); error E14(); error E15(); error E16(); error E17(); error E18(); error E19(); error E20();
    error E21(); error E22(); error E23(); error E24(); error E25(); error E26(); error E27(); error E28(); error E29(); error E30();
    error E31(); error E32(); error E33(); error E34(); error E35(); error E36(); error E37(); error E38(); error E39(); error E40();
    error E41(); error E42(); error E43(); error E44(); error E45(); error E46(); error E47(); error E48();

    // === EVENT ENUM FOR OPTIMIZATION ===
    enum EventType {
        MaxSecondaryAddressesUpdated,
        PublicRegistrarRegistrationToggled,
        EmergencyModeToggled,
        UnifiedIdLengthLimitsUpdated,
        UtilImplementationUpdated,
        ResolverUpdated,
        ChainIdUpdated,
        AuthorizedRelayerUpdated,
        EmergencyUnifiedIdMarked,
        EmergencyRegistrarRemoved,
        SecondaryAddressAdded,
        SecondaryAddressRemoved,
        RegistrarRegistered,
        RegistrationPaused,
        RegistrationUnpaused,
        UnifiedIDRegistered,
        UnifiedIDUpdated,
        UnifiedIDChanged,
        RegisterUnifiedIdInitiated,
        UpdateUnifiedIdInitiated,
        UpdateUnifiedIdPrimaryAddressInitiated,
        AddSecondaryAddressInitiated,
        RemoveSecondaryAddressInitiated,
        EthWithdrawn,
        ERC20Withdrawn,
        OwnershipTransferStarted,
        OwnershipTransferred
    }

    // === SINGLE UNIFIED EVENT ===
    event UnifiedEvent(EventType indexed eventType, bytes data);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // === OWNABLE2STEP IMPLEMENTATION ===
    address private _owner;
    address private _pendingOwner;

    function owner() public view virtual returns (address) {
        return _owner;
    }

    function pendingOwner() public view virtual returns (address) {
        return _pendingOwner;
    }

    modifier onlyOwner() {
        if (owner() != msg.sender) revert E1();
        _;
    }

    function renounceOwnership() public virtual onlyOwner {
        _transferOwnership(address(0));
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        if (newOwner == address(0)) revert E2();
        _pendingOwner = newOwner;
        emit UnifiedEvent(EventType.OwnershipTransferStarted, abi.encode(owner(), newOwner));
    }

    function acceptOwnership() external {
        address sender = msg.sender;
        if (pendingOwner() != sender) revert E3();
        _transferOwnership(sender);
    }

    function _transferOwnership(address newOwner) internal virtual {
        delete _pendingOwner;
        address oldOwner = _owner;
        _owner = newOwner;
        emit UnifiedEvent(EventType.OwnershipTransferred, abi.encode(oldOwner, newOwner));
    }

    // === OPTIMIZED STORAGE STRUCTS ===
    struct UserData {
        address primary;
        mapping(address => bool) isSecondary;
        address[] secondaries;
        bool exists;
    }

    struct PackedConfig {
        uint8 maxSecondaryAddresses;
        uint8 minUnifiedIdLength;
        uint8 maxUnifiedIdLength;
        bool isPaused;
        bool publicRegistrarRegistration;
        bool emergencyMode;
    }

    PackedConfig public config;

    // === STATE VARIABLES ===
    uint256 public totalRegisteredUnifiedIds;
    uint256 public chainId;

    RegistrarStorageUtil public util;
    IUnifiedIdResolver public resolver;

    address[] public registrarAddresses;

    // Optimized mappings using bytes32
    mapping(bytes32 => address) public registrarNameToAddress;
    mapping(address => uint8) public totalRegistrarUpdates;
    mapping(bytes32 => UserData) private userAddresses;
    mapping(bytes32 => bool) public unavailableUnifiedIds;
    mapping(bytes32 => bool) public registeredUnifiedIds;
    mapping(bytes32 => address) public resolveAddressFromUnifiedId;
    mapping(address => bytes32) public resolveUnifiedIdFromAddress;
    mapping(bytes32 => mapping(uint256 => bool)) public usedNonces;

    string[] public registrarNames;

    // === HELPER FUNCTION FOR STRING TO BYTES32 ===
    function _toBytes32(string memory str) private pure returns (bytes32) {
        return keccak256(bytes(str));
    }

    // === MODIFIERS ===
    modifier unifiedIdExists(string calldata _unifiedId) {
        if (!userAddresses[_toBytes32(_unifiedId)].exists) revert E4();
        _;
    }

    modifier whenNotPaused() {
        if (config.isPaused) revert E5();
        _;
    }

    modifier unifiedIdDoesNotExist(string calldata _unifiedId) {
        bytes32 id = _toBytes32(_unifiedId);
        if (userAddresses[id].exists) revert E6();
        if (unavailableUnifiedIds[id]) revert E7();
        _;
    }

    modifier validateRegistrarName(string memory _registrarName) {
        bytes32 nameHash = _toBytes32(_registrarName);
        if (registrarNameToAddress[nameHash] != address(0)) revert E8();
        if (resolveAddressFromUnifiedId[nameHash] != address(0)) revert E9();
        _;
    }

    modifier onlyRegistrar() {
        require(hasRole(REGISTRAR_ROLE, msg.sender));
        _;
    }

    modifier onlyAuthorizedRelayer() {
        require(hasRole(RELAYER_ROLE, msg.sender));
        _;
    }

    modifier onlyAdmin() {
        require(hasRole(ADMIN_ROLE, msg.sender) || msg.sender == owner());
        _;
    }

    modifier notInEmergencyMode() {
        if (config.emergencyMode) revert E13();
        _;
    }

    modifier publicRegistrarAllowed() {
        if (!config.publicRegistrarRegistration && !hasRole(ADMIN_ROLE, msg.sender) && msg.sender != owner()) revert E14();
        _;
    }

    modifier onlyEmergency() {
        require(hasRole(EMERGENCY_ROLE, msg.sender) || hasRole(ADMIN_ROLE, msg.sender) || msg.sender == owner());
        _;
    }

    function _authorizeUpgrade(address /* newImplementation */) internal view override {
        require(hasRole(UPGRADER_ROLE, msg.sender) || msg.sender == owner());
    }

    function initialize(address _RegistrarStorageUtil, address _resolver, uint256 _chainId) public initializer {
        __UUPSUpgradeable_init();
        __AccessControl_init();

        _owner = msg.sender;
        emit UnifiedEvent(EventType.OwnershipTransferred, abi.encode(address(0), msg.sender));

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(EMERGENCY_ROLE, msg.sender);
        _grantRole(UPGRADER_ROLE, msg.sender);

        util = RegistrarStorageUtil(_RegistrarStorageUtil);
        resolver = IUnifiedIdResolver(_resolver);
        chainId = _chainId;

        config = PackedConfig({
            maxSecondaryAddresses: 10,
            minUnifiedIdLength: 4,
            maxUnifiedIdLength: 16,
            isPaused: false,
            publicRegistrarRegistration: false,
            emergencyMode: false
        });
    }

    function setUtilImplementation(address _RegistrarStorageUtil) external onlyRole(ADMIN_ROLE) {
        if (_RegistrarStorageUtil == address(0)) revert E15();
        address oldUtil = address(util);
        util = RegistrarStorageUtil(_RegistrarStorageUtil);
        emit UnifiedEvent(EventType.UtilImplementationUpdated, abi.encode(oldUtil, _RegistrarStorageUtil, msg.sender));
    }

    function setResolver(address _resolver) external onlyRole(ADMIN_ROLE) {
        if (_resolver == address(0)) revert E16();
        address oldResolver = address(resolver);
        resolver = IUnifiedIdResolver(_resolver);
        emit UnifiedEvent(EventType.ResolverUpdated, abi.encode(oldResolver, _resolver, msg.sender));
    }

    function setChainId(uint256 _chainId) external onlyRole(ADMIN_ROLE) {
        uint256 oldChainId = chainId;
        chainId = _chainId;
        emit UnifiedEvent(EventType.ChainIdUpdated, abi.encode(oldChainId, _chainId, msg.sender));
    }

    function registerRegistrar(string calldata _registrarName, address _registrarAddress) external payable whenNotPaused validateRegistrarName(_registrarName) publicRegistrarAllowed notInEmergencyMode returns (bool) {
        if (_registrarAddress == address(0)) revert E18();
        if (_isAddressTaken(_registrarAddress)) revert E19();

        bytes32 nameHash = _toBytes32(_registrarName);
        registrarNameToAddress[nameHash] = _registrarAddress;
        registrarAddresses.push(_registrarAddress);
        registrarNames.push(_registrarName);

        _grantRole(REGISTRAR_ROLE, _registrarAddress);
        emit UnifiedEvent(EventType.RegistrarRegistered, abi.encode(_registrarAddress, _registrarName));
        return true;
    }

    function pauseRegistration() external onlyRole(ADMIN_ROLE) {
        config.isPaused = true;
        emit UnifiedEvent(EventType.RegistrationPaused, abi.encode(msg.sender));
    }

    function unpauseRegistration() external onlyRole(ADMIN_ROLE) {
        config.isPaused = false;
        emit UnifiedEvent(EventType.RegistrationUnpaused, abi.encode(msg.sender));
    }

    function initiateRegisterUnifiedId(string calldata _unifiedId, address _primaryAddress, bytes calldata _masterSignature, bytes calldata _primarySignature, bytes calldata _options) external payable whenNotPaused onlyRegistrar returns (bool) {
        if (!util.isUnifiedIdValid(_unifiedId)) revert E20();
        bytes32 id = _toBytes32(_unifiedId);
        if (userAddresses[id].exists) revert E6();
        if (unavailableUnifiedIds[id]) revert E7();
        if (registrarNameToAddress[id] != address(0)) revert E21();
        if (resolveAddressFromUnifiedId[id] != address(0)) revert E22();

        emit UnifiedEvent(EventType.RegisterUnifiedIdInitiated, abi.encode(_unifiedId, _primaryAddress, _masterSignature, _primarySignature, _options));
        return true;
    }

    function completeRegisterUnifiedId(string calldata _unifiedId, address _primaryAddress, bytes calldata _masterSignature, bytes calldata _primarySignature, uint256 _nonce, uint256 _timestamp) external whenNotPaused onlyAuthorizedRelayer returns (bool) {
        if (block.timestamp > _timestamp + 1 hours) revert E23();

        bytes32 id = _toBytes32(_unifiedId);
        if (usedNonces[id][_nonce]) revert E24();

        bytes memory message = abi.encode("REGISTER_UNIFIED_ID", _unifiedId, _primaryAddress, chainId, _nonce, _timestamp);

        if (!util.verifySignature(message, _primaryAddress, _primarySignature)) revert E25();

        if (_masterSignature.length != 0) {
            if (!util.verifySignature(message, _primaryAddress, _masterSignature)) revert E26();
        }

        usedNonces[id][_nonce] = true;

        UserData storage userData = userAddresses[id];
        userData.primary = _primaryAddress;
        userData.exists = true;

        resolveAddressFromUnifiedId[id] = _primaryAddress;
        resolveUnifiedIdFromAddress[_primaryAddress] = id;
        registeredUnifiedIds[id] = true;
        totalRegisteredUnifiedIds++;
        unavailableUnifiedIds[id] = true;

        resolver.setUnifiedIdPrimaryAddress(_unifiedId, chainId, _primaryAddress);

        emit UnifiedEvent(EventType.UnifiedIDRegistered, abi.encode(_unifiedId, _primaryAddress, block.timestamp));
        return true;
    }

    function initiateUpdateUnifiedId(string calldata _oldUnifiedId, string calldata _newUnifiedId, bytes calldata _signature, bytes calldata _options) external payable whenNotPaused unifiedIdExists(_oldUnifiedId) unifiedIdDoesNotExist(_newUnifiedId) onlyRegistrar returns (bool) {
        if (!util.isUnifiedIdValid(_newUnifiedId)) revert E27();
        emit UnifiedEvent(EventType.UpdateUnifiedIdInitiated, abi.encode(_oldUnifiedId, _newUnifiedId, _signature, _options));
        return true;
    }

    function completeUpdateUnifiedId(string memory _oldUnifiedId, string memory _newUnifiedId, bytes calldata _signature, uint256 _nonce, uint256 _timestamp) external whenNotPaused onlyAuthorizedRelayer returns (bool) {
        bytes32 oldId = _toBytes32(_oldUnifiedId);
        bytes32 newId = _toBytes32(_newUnifiedId);

        if (!registeredUnifiedIds[oldId]) revert E28();
        if (registeredUnifiedIds[newId]) revert E29();
        if (oldId == newId) revert E46();

        UserData storage userData = userAddresses[oldId];
        address currentPrimary = userData.primary;

        if (block.timestamp > _timestamp + 1 hours) revert E23();
        if (usedNonces[oldId][_nonce]) revert E24();

        bytes memory message = abi.encode("UPDATE_UNIFIED_ID", _oldUnifiedId, _newUnifiedId, chainId, _nonce, _timestamp);

        if (!util.verifySignature(message, currentPrimary, _signature)) revert E30();

        usedNonces[oldId][_nonce] = true;

        address primaryAddress = currentPrimary;

        resolveAddressFromUnifiedId[newId] = primaryAddress;
        delete resolveAddressFromUnifiedId[oldId];
        resolveUnifiedIdFromAddress[primaryAddress] = newId;

        UserData storage newUserData = userAddresses[newId];
        newUserData.primary = primaryAddress;
        newUserData.exists = true;

        resolver.clearUnifiedIdMappings(_oldUnifiedId, chainId);
        resolver.setUnifiedIdPrimaryAddress(_newUnifiedId, chainId, primaryAddress);

        uint256 secLength = userData.secondaries.length;
        for (uint256 i; i < secLength;) {
            address secondaryAddr = userData.secondaries[i];
            if (newUserData.isSecondary[secondaryAddr]) revert E31();

            newUserData.isSecondary[secondaryAddr] = true;
            newUserData.secondaries.push(secondaryAddr);
            resolver.addUnifiedIdSecondaryAddress(_newUnifiedId, chainId, secondaryAddr);

            unchecked { ++i; }
        }

        delete registeredUnifiedIds[oldId];
        registeredUnifiedIds[newId] = true;
        unavailableUnifiedIds[oldId] = true;
        unavailableUnifiedIds[newId] = true;
        delete userAddresses[oldId];

        emit UnifiedEvent(EventType.UnifiedIDChanged, abi.encode(_oldUnifiedId, _newUnifiedId, primaryAddress, block.timestamp));
        return true;
    }

    function initiatePrimaryAddressChange(string calldata _unifiedId, address _newPrimaryAddress, bytes calldata currentPrimarySignature, bytes calldata newPrimarySignature, bytes calldata _options) external payable whenNotPaused unifiedIdExists(_unifiedId) onlyRegistrar returns (bool) {
        emit UnifiedEvent(EventType.UpdateUnifiedIdPrimaryAddressInitiated, abi.encode(_unifiedId, _newPrimaryAddress, currentPrimarySignature, newPrimarySignature, _options));
        return true;
    }

    function finalizePrimaryAddressChange(string calldata _unifiedId, address _newPrimaryAddress, bytes calldata _currentPrimarySignature, bytes calldata _newPrimarySignature, uint256 _nonce, uint256 _timestamp) external whenNotPaused onlyAuthorizedRelayer returns (bool) {
        bytes32 id = _toBytes32(_unifiedId);
        UserData storage userData = userAddresses[id];
        address oldPrimary = userData.primary;

        if (oldPrimary == _newPrimaryAddress) revert E47();
        if (_newPrimaryAddress == address(0)) revert E48();
        if (block.timestamp > _timestamp + 1 hours) revert E23();
        if (usedNonces[id][_nonce]) revert E24();

        bytes memory message = abi.encode("UPDATE_PRIMARY_ADDRESS", _unifiedId, _newPrimaryAddress, chainId, _nonce, _timestamp);

        if (!util.verifySignature(message, oldPrimary, _currentPrimarySignature)) revert E32();
        if (!util.verifySignature(message, _newPrimaryAddress, _newPrimarySignature)) revert E33();

        usedNonces[id][_nonce] = true;
        userData.primary = _newPrimaryAddress;
        resolveAddressFromUnifiedId[id] = _newPrimaryAddress;
        resolveUnifiedIdFromAddress[_newPrimaryAddress] = id;
        resolveUnifiedIdFromAddress[oldPrimary] = bytes32(0);

        resolver.updateUnifiedIdPrimaryAddress(_unifiedId, chainId, _newPrimaryAddress);

        emit UnifiedEvent(EventType.UnifiedIDUpdated, abi.encode(_unifiedId, oldPrimary, _newPrimaryAddress));
        return true;
    }

    function initiateAddSecondaryAddress(string calldata _unifiedId, address _secondaryAddress, bytes calldata _primarySignature, bytes calldata _secondarySignature, bytes calldata _options) external payable whenNotPaused unifiedIdExists(_unifiedId) onlyRegistrar returns (bool) {
        bytes32 id = _toBytes32(_unifiedId);
        UserData storage userData = userAddresses[id];

        if (userData.primary == _secondaryAddress) revert E34();
        if (userData.isSecondary[_secondaryAddress]) revert E35();
        if (userData.secondaries.length >= config.maxSecondaryAddresses) revert E36();

        emit UnifiedEvent(EventType.AddSecondaryAddressInitiated, abi.encode(_unifiedId, _secondaryAddress, _primarySignature, _secondarySignature, _options));
        return true;
    }

    function completeAddSecondaryAddress(string calldata _unifiedId, address _secondaryAddress, bytes calldata _primarySignature, bytes calldata _secondarySignature, uint256 _nonce, uint256 _timestamp) external whenNotPaused onlyAuthorizedRelayer returns (bool) {
        bytes32 id = _toBytes32(_unifiedId);
        UserData storage userData = userAddresses[id];

        if (userData.primary == _secondaryAddress) revert E34();
        if (userData.isSecondary[_secondaryAddress]) revert E35();
        if (block.timestamp > _timestamp + 1 hours) revert E23();
        if (usedNonces[id][_nonce]) revert E24();

        bytes memory message = abi.encode("ADD_SECONDARY_ADDRESS", _unifiedId, _secondaryAddress, chainId, _nonce, _timestamp);

        if (!util.verifySignature(message, userData.primary, _primarySignature)) revert E25();
        if (!util.verifySignature(message, _secondaryAddress, _secondarySignature)) revert E37();

        usedNonces[id][_nonce] = true;
        userData.isSecondary[_secondaryAddress] = true;
        userData.secondaries.push(_secondaryAddress);

        resolver.addUnifiedIdSecondaryAddress(_unifiedId, chainId, _secondaryAddress);

        emit UnifiedEvent(EventType.SecondaryAddressAdded, abi.encode(_unifiedId, _secondaryAddress));
        return true;
    }

    function initiateRemoveSecondaryAddress(string calldata _unifiedId, address _secondaryAddress, bytes calldata _signature, bytes calldata _options) external payable whenNotPaused unifiedIdExists(_unifiedId) onlyRegistrar returns (bool) {
        emit UnifiedEvent(EventType.RemoveSecondaryAddressInitiated, abi.encode(_unifiedId, _secondaryAddress, _signature, _options));
        return true;
    }

    function completeRemoveSecondaryAddress(string calldata _unifiedId, address _secondaryAddress, bytes calldata _signature, uint256 _nonce, uint256 _timestamp) external whenNotPaused onlyAuthorizedRelayer returns (bool) {
        bytes32 id = _toBytes32(_unifiedId);
        UserData storage userData = userAddresses[id];

        if (block.timestamp > _timestamp + 1 hours) revert E23();
        if (usedNonces[id][_nonce]) revert E24();

        bytes memory message = abi.encode("REMOVE_SECONDARY_ADDRESS", _unifiedId, _secondaryAddress, chainId, _nonce, _timestamp);

        if (!util.verifySignature(message, userData.primary, _signature)) revert E30();

        usedNonces[id][_nonce] = true;
        userData.isSecondary[_secondaryAddress] = false;

        uint256 length = userData.secondaries.length;
        for (uint256 i; i < length;) {
            if (userData.secondaries[i] == _secondaryAddress) {
                userData.secondaries[i] = userData.secondaries[length - 1];
                userData.secondaries.pop();
                break;
            }
            unchecked { ++i; }
        }

        resolver.removeUnifiedIdSecondaryAddress(_unifiedId, chainId, _secondaryAddress);

        emit UnifiedEvent(EventType.SecondaryAddressRemoved, abi.encode(_unifiedId, _secondaryAddress));
        return true;
    }

    // === VIEW FUNCTIONS ===
    function isPrimaryAddress(string calldata _unifiedId, address _address) external view returns (bool) {
        return userAddresses[_toBytes32(_unifiedId)].primary == _address;
    }

    function isSecondaryAddress(string calldata _unifiedId, address _address) external view returns (bool) {
        return userAddresses[_toBytes32(_unifiedId)].isSecondary[_address];
    }

    function getPrimaryAddress(string calldata _unifiedId) external view returns (address) {
        return userAddresses[_toBytes32(_unifiedId)].primary;
    }

    function getSecondaryAddresses(string calldata _unifiedId) external view returns (address[] memory) {
        return userAddresses[_toBytes32(_unifiedId)].secondaries;
    }

    function getTotalRegisteredUnifiedIds() external view returns (uint256) {
        return totalRegisteredUnifiedIds;
    }

    function resolveAddressToUnifiedId(address addr) external view returns (string memory) {
        return resolver.getUnifiedIdFromAddress(addr, chainId);
    }

    function resolvePrimaryAddress(string calldata unifiedId) external view returns (address) {
        return resolver.getPrimaryAddress(unifiedId, chainId);
    }

    function resolveAllAddresses(string calldata unifiedId) external view returns (address primary, address[] memory secondaries) {
        return resolver.getAddresses(unifiedId, chainId);
    }

    function resolveAddressAssociation(string calldata unifiedId, address addr) external view returns (bool isPrimary, bool isSecondary) {
        return resolver.isAddressAssociated(unifiedId, chainId, addr);
    }

    function resolveSecondaryAddressToUnifiedId(address secondaryAddr) external view returns (string memory) {
        return resolver.resolveSecondaryAddressToUnifiedId(secondaryAddr, chainId);
    }

    function resolveAnyAddressToUnifiedId(address addr) external view returns (string memory unifiedId, bool isPrimary, bool isSecondary) {
        return resolver.resolveAnyAddressToUnifiedId(addr, chainId);
    }

    function getAllAddresses(string calldata unifiedId) external view returns (address[] memory allAddresses) {
        return resolver.getAllAddresses(unifiedId, chainId);
    }

    function getAddressCount(string calldata unifiedId) external view returns (uint256 count) {
        return resolver.getAddressCount(unifiedId, chainId);
    }

    function hasMultipleAddresses(string calldata unifiedId) external view returns (bool hasMultiple) {
        return resolver.getAddressCount(unifiedId, chainId) > 1;
    }

    // === UNIFIED ROLE MANAGEMENT ===
    function manageRole(bytes32 role, address account, bool grant) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (grant) {
            _grantRole(role, account);
        } else {
            _revokeRole(role, account);
        }

        if (role == RELAYER_ROLE) {
            emit UnifiedEvent(EventType.AuthorizedRelayerUpdated, abi.encode(account, grant, msg.sender));
        }
    }

    // === ROLE CHECKING FUNCTIONS ===
    function isRelayer(address account) external view returns (bool) {
        return hasRole(RELAYER_ROLE, account);
    }

    function isRegistrar(address account) external view returns (bool) {
        return hasRole(REGISTRAR_ROLE, account);
    }

    function isAdmin(address account) external view returns (bool) {
        return hasRole(ADMIN_ROLE, account);
    }

    function isEmergencyResponder(address account) external view returns (bool) {
        return hasRole(EMERGENCY_ROLE, account);
    }

    function isUpgrader(address account) external view returns (bool) {
        return hasRole(UPGRADER_ROLE, account);
    }

    // === ADMIN FUNCTIONS ===
    function setMaxSecondaryAddresses(uint256 _maxSecondaryAddresses) external onlyRole(ADMIN_ROLE) {
        uint256 oldMax = config.maxSecondaryAddresses;
        config.maxSecondaryAddresses = uint8(_maxSecondaryAddresses);
        emit UnifiedEvent(EventType.MaxSecondaryAddressesUpdated, abi.encode(oldMax, _maxSecondaryAddresses));
    }

    function setRegistrarRegistrationPermission(bool _enabled) external onlyRole(ADMIN_ROLE) {
        config.publicRegistrarRegistration = _enabled;
        emit UnifiedEvent(EventType.PublicRegistrarRegistrationToggled, abi.encode(_enabled));
    }

    function setEmergencyMode(bool _enabled) external onlyRole(EMERGENCY_ROLE) {
        config.emergencyMode = _enabled;
        emit UnifiedEvent(EventType.EmergencyModeToggled, abi.encode(_enabled));
    }

    function setUnifiedIdLengthLimits(uint256 _minLength, uint256 _maxLength) external onlyRole(ADMIN_ROLE) {
        if (_minLength == 0 || _maxLength <= _minLength) revert E39();
        config.minUnifiedIdLength = uint8(_minLength);
        config.maxUnifiedIdLength = uint8(_maxLength);
        emit UnifiedEvent(EventType.UnifiedIdLengthLimitsUpdated, abi.encode(_minLength, _maxLength));
    }

    function emergencyMarkUnavailable(string calldata _unifiedId) external onlyEmergency {
        bytes32 id = _toBytes32(_unifiedId);
        unavailableUnifiedIds[id] = true;
        emit UnifiedEvent(EventType.EmergencyUnifiedIdMarked, abi.encode(_unifiedId, false, msg.sender));
    }

    function emergencyMarkAvailable(string calldata _unifiedId) external onlyEmergency {
        bytes32 id = _toBytes32(_unifiedId);
        unavailableUnifiedIds[id] = false;
        emit UnifiedEvent(EventType.EmergencyUnifiedIdMarked, abi.encode(_unifiedId, true, msg.sender));
    }

    function emergencyRemoveRegistrar(address _registrarAddress) external onlyEmergency {
        if (!hasRole(REGISTRAR_ROLE, _registrarAddress)) revert E40();

        string memory registrarName = getRegistrarName(_registrarAddress);
        _revokeRole(REGISTRAR_ROLE, _registrarAddress);
        bytes32 nameHash = _toBytes32(registrarName);
        registrarNameToAddress[nameHash] = address(0);
        delete registrarNameToAddress[nameHash];

        uint256 length = registrarAddresses.length;
        for (uint256 i; i < length;) {
            if (registrarAddresses[i] == _registrarAddress) {
                registrarAddresses[i] = registrarAddresses[length - 1];
                registrarAddresses.pop();
                registrarNames[i] = registrarNames[length - 1];
                registrarNames.pop();
                break;
            }
            unchecked { ++i; }
        }

        emit UnifiedEvent(EventType.EmergencyRegistrarRemoved, abi.encode(_registrarAddress, registrarName, msg.sender));
    }

    function getConfiguration() external view returns (uint256, bool, bool, uint256, uint256) {
        return (config.maxSecondaryAddresses, config.publicRegistrarRegistration, config.emergencyMode, config.minUnifiedIdLength, config.maxUnifiedIdLength);
    }

    function getAllRegistrars() external view returns (address[] memory) {
        return registrarAddresses;
    }

    function getAllRegistrarsWithNames() external view returns (address[] memory addresses, string[] memory names) {
        return (registrarAddresses, registrarNames);
    }

    function getTotalRegistrars() external view returns (uint256) {
        return registrarAddresses.length;
    }

    function getRegistrarInfo(address _address) external view returns (bool isReg, string memory registrarName, uint8 updateCount) {
        return (hasRole(REGISTRAR_ROLE, _address), getRegistrarName(_address), totalRegistrarUpdates[_address]);
    }

    receive() external payable {}
    fallback() external payable {}

    function withdrawEth(address payable to, uint256 amount) external onlyOwner whenNotPaused {
        if (to == address(0)) revert E41();
        if (amount > address(this).balance) revert E42();

        (bool success, ) = to.call{value: amount}("");
        if (!success) revert E43();

        emit UnifiedEvent(EventType.EthWithdrawn, abi.encode(to, amount));
    }

    function withdrawERC20(address token, address to, uint256 amount) external onlyOwner whenNotPaused {
        if (token == address(0)) revert E44();
        if (to == address(0)) revert E41();

        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, amount));
        if (!success || (data.length != 0 && !abi.decode(data, (bool)))) revert E45();

        emit UnifiedEvent(EventType.ERC20Withdrawn, abi.encode(token, to, amount));
    }

    function getRegistrarName(address _address) public view returns (string memory) {
        for (uint256 i = 0; i < registrarAddresses.length; i++) {
            if (registrarAddresses[i] == _address) {
                return registrarNames[i];
            }
        }
        return "";
    }

    // === INTERNAL HELPER FUNCTION ===
    function _isAddressTaken(address _address) private view returns (bool) {
        for (uint256 i = 0; i < registrarAddresses.length; i++) {
            if (registrarAddresses[i] == _address) {
                return true;
            }
        }
        return false;
    }
}

contracts/RegistrarStorageUtil.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.25;

import {AggregatorV3Interface} from "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

/**
 * @title RegistrarStorageUtil
 * @author kunalmkv
 * @notice Utility contract for price feeds, signature verification, and admin management with role-based access control
 * @dev Implements secure signature verification with EIP-712, price feed management, two-step ownership, and OpenZeppelin AccessControl
 * @dev Uses UUPS upgradeable pattern with comprehensive authorization controls
 */
contract RegistrarStorageUtil is Initializable, UUPSUpgradeable, AccessControlUpgradeable {

    // ==================== ROLE DEFINITIONS ====================

    /// @notice Role for admin users with elevated privileges
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Role for price feed managers
    bytes32 public constant PRICE_FEED_MANAGER_ROLE = keccak256("PRICE_FEED_MANAGER_ROLE");

    /// @notice Role for configuration managers
    bytes32 public constant CONFIG_MANAGER_ROLE = keccak256("CONFIG_MANAGER_ROLE");

    /// @notice Mapping of token addresses to their corresponding Chainlink price feed addresses
    mapping(address => address) public tokenPriceFeed;

    /// @notice Mapping of token addresses to their decimal precision
    mapping(address => uint256) public tokenDecimal;

    /// @notice Address of ETH/USD Chainlink price feed
    address public ethPriceFeed;

    // === OWNABLE2STEP IMPLEMENTATION ===
    /// @dev Address of the current contract owner
    address private _owner;

    /// @dev Address of the pending owner during ownership transfer
    address private _pendingOwner;

    /// @dev Ethereum signed message prefix for signature verification
    string constant PREFIX = "\x19Ethereum Signed Message:\n32";

    // === ADMIN CONFIGURATION VARIABLES ===
    /// @notice Maximum allowed length for unified IDs
    uint8 public maxUnifiedIdLength;

    /// @notice Minimum required length for unified IDs
    uint8 public minUnifiedIdLength;

    // === ADMIN EVENTS ===

    /**
     * @notice Emitted when unified ID length limits are updated
     * @param minLength New minimum length requirement
     * @param maxLength New maximum length requirement
     */
    event UnifiedIdLengthLimitsUpdated(uint8 minLength, uint8 maxLength);

    /**
     * @notice Emitted when ownership transfer is initiated
     * @param previousOwner Current owner who initiated the transfer
     * @param newOwner Address that will become the new owner
     */
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);

    /**
     * @notice Emitted when ownership transfer is completed
     * @param previousOwner Previous owner address
     * @param newOwner New owner address
     */
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // Events

    /**
     * @notice Emitted when a token price feed is configured
     * @param token Token address for which price feed was set
     * @param priceFeed Chainlink price feed address
     */
    event TokenPriceFeedSet(address indexed token, address indexed priceFeed);

    /**
     * @notice Emitted when ETH price feed is configured
     * @param priceFeed Chainlink ETH/USD price feed address
     */
    event EthPriceFeedSet(address indexed priceFeed);

    // === MISSING CRITICAL EVENTS ===

    /**
     * @notice Emitted when token decimal precision is updated
     * @param token Token address whose decimal was updated
     * @param oldDecimal Previous decimal value
     * @param newDecimal New decimal value
     */
    event TokenDecimalUpdated(address indexed token, uint256 oldDecimal, uint256 newDecimal);

    /**
     * @notice Constructor disables initializers to prevent implementation contract initialization
     * @dev This is a security measure for upgradeable contracts
     */
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initializes the contract with default values and role-based access control
     * @dev Sets deployer as owner and admin, establishes default unified ID length limits, and sets up roles
     * @param initialOwner Address that will become the initial owner and admin
     */
    function initialize(address initialOwner) public initializer {
        __AccessControl_init();
        __UUPSUpgradeable_init();

        require(initialOwner != address(0), "Initial owner cannot be zero address");

        _owner = initialOwner;
        maxUnifiedIdLength = 16;
        minUnifiedIdLength = 4;

        // Setup roles
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        _grantRole(ADMIN_ROLE, initialOwner);
        _grantRole(PRICE_FEED_MANAGER_ROLE, initialOwner);
        _grantRole(CONFIG_MANAGER_ROLE, initialOwner);

        emit OwnershipTransferred(address(0), initialOwner);
    }

    /**
     * @notice Authorizes contract upgrades
     * @dev Only admin or owner can authorize upgrades
     * @param newImplementation Address of the new implementation contract
     */
    function _authorizeUpgrade(address newImplementation) internal view override {
        require(hasRole(ADMIN_ROLE, msg.sender) || msg.sender == owner(), "AccessControl: caller is not admin or owner");
        // Silence unused parameter warning
        newImplementation;
    }

    /**
     * @notice Returns the address of the current owner
     * @return Address of the current contract owner
     */
    function owner() public view virtual returns (address) {
        return _owner;
    }

    /**
     * @notice Returns the address of the pending owner during ownership transfer
     * @return Address of the pending owner, or zero address if no transfer is pending
     */
    function pendingOwner() public view virtual returns (address) {
        return _pendingOwner;
    }

    /**
     * @notice Modifier to restrict access to owner only
     * @dev Reverts if caller is not the current owner
     */
    modifier onlyOwner() {
        require(owner() == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    /**
     * @notice Modifier to restrict access to admin users or owner
     * @dev Reverts if caller is neither admin nor owner
     */
    modifier onlyAdmin() {
        require(hasRole(ADMIN_ROLE, msg.sender) || msg.sender == owner(), "AccessControl: caller is not admin or owner");
        _;
    }

    /**
     * @notice Renounces ownership of the contract
     * @dev Leaves the contract without owner, disabling owner-only functions permanently
     * @dev Can only be called by the current owner
     * @dev WARNING: This action is irreversible
     */
    function renounceOwnership() public virtual onlyOwner {
        _transferOwnership(address(0));
    }

    /**
     * @notice Initiates ownership transfer to a new account (Step 1 of 2)
     * @dev The new owner must call acceptOwnership() to complete the transfer
     * @param newOwner Address of the proposed new owner
     * @custom:requirements
     * - newOwner cannot be zero address
     * - newOwner cannot be the current owner
     * - Only current owner can call this function
     */
    function transferOwnership(address newOwner) public virtual onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        require(newOwner != owner(), "Ownable: new owner is the same as current owner");
        _pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner(), newOwner);
    }

    /**
     * @notice Accepts ownership transfer (Step 2 of 2)
     * @dev Completes the two-step ownership transfer process
     * @dev Only the pending owner can call this function
     * @custom:requirements
     * - Caller must be the pending owner
     * - A transfer must be pending
     */
    function acceptOwnership() external {
        address sender = msg.sender;
        require(pendingOwner() == sender, "Ownable2Step: caller is not the new owner");
        _transferOwnership(sender);
    }

    /**
     * @dev Internal function to transfer ownership
     * @param newOwner Address of the new owner
     */
    function _transferOwnership(address newOwner) internal virtual {
        delete _pendingOwner;
        address oldOwner = _owner;
        _owner = newOwner;
        if (newOwner != address(0)) {
            _grantRole(ADMIN_ROLE, newOwner);
            _grantRole(PRICE_FEED_MANAGER_ROLE, newOwner);
            _grantRole(CONFIG_MANAGER_ROLE, newOwner);
        }
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    /**
     * @notice Sets the price feed for a specific token
     * @dev Configures Chainlink price feed and decimal precision for token calculations
     * @param token Address of the token contract
     * @param priceFeed Address of the Chainlink price feed for this token
     * @param decimal Decimal precision for the token
     * @custom:requirements
     * - Only price feed manager can call this function
     * - token cannot be zero address
     * - priceFeed cannot be zero address
     * @custom:events
     * - Emits TokenPriceFeedSet
     * - Emits TokenDecimalUpdated if decimal value changed
     */
    function setTokenPriceFeed(address token, address priceFeed, uint256 decimal) external onlyRole(PRICE_FEED_MANAGER_ROLE) {
        require(token != address(0), "Token: zero address");
        require(priceFeed != address(0), "Price feed: zero address");

        uint256 oldDecimal = tokenDecimal[token];
        tokenPriceFeed[token] = priceFeed;
        tokenDecimal[token] = decimal;

        emit TokenPriceFeedSet(token, priceFeed);
        if (oldDecimal != decimal) {
            emit TokenDecimalUpdated(token, oldDecimal, decimal);
        }
    }

    /**
     * @notice Sets the ETH/USD price feed address
     * @dev Configures the Chainlink ETH/USD price feed for ETH price calculations
     * @param _ethPriceFeed Address of the Chainlink ETH/USD price feed
     * @custom:requirements
     * - Only price feed manager can call this function
     * - _ethPriceFeed cannot be zero address
     * @custom:events
     * - Emits EthPriceFeedSet
     */
    function setEthPriceFeed(address _ethPriceFeed) external onlyRole(PRICE_FEED_MANAGER_ROLE) {
        require(_ethPriceFeed != address(0), "ETH price feed: zero address");
        ethPriceFeed = _ethPriceFeed;
        emit EthPriceFeedSet(_ethPriceFeed);
    }

    /**
     * @notice Calculates required token amount based on registrar fees
     * @dev Converts registrar fees from ETH to specified token using Chainlink price feeds
     * @param token Address of the payment token (zero address for ETH)
     * @param registrarFees Fee amount in ETH wei
     * @return Required token amount adjusted for token decimals
     * @custom:requirements
     * - Token and ETH price feeds must be configured
     * - Price feed data must be valid (positive)
     * @custom:calculations
     * - For ETH: returns fees directly
     * - For tokens: converts ETH amount to token amount using price feeds
     * - Handles decimal adjustments between token and ETH price feeds
     */
    function getRequiredTokenAmount(address token, uint256 registrarFees) external view returns (uint256) {
        if (token == address(0)) {
            return registrarFees;
        } else {

            uint256[] memory tokenInfo = getTokenAmount(token);
            uint256 tokenPriceInUSD = tokenInfo[0]; // Token USD price (Chainlink decimals = 8)
            uint256 tokenDecimals = tokenInfo[1];   // Token decimals (e.g., USDC = 6)
            uint256 ethPriceInUSD = tokenInfo[2];   // ETH USD price (Chainlink decimals = 8)
            // Note: ethDecimals (tokenInfo[3]) is not used in this function but kept for API consistency

            require(tokenPriceInUSD > 0 && ethPriceInUSD > 0, "Invalid price data");

            // STEP 1: Convert registrarFees (wei, 18 decimals) to USD (standardized 8 decimals)
            uint256 registrarFeeInUSD = (registrarFees * ethPriceInUSD) / 1e18;
            // registrarFees(1e18) * ethPriceInUSD(1e8) / 1e18 → 1e8 precision USD value

            // STEP 2: Convert USD amount (8 decimals) to token amount using token price (8 decimals)
            uint256 tokenAmount = (registrarFeeInUSD * (10 ** tokenDecimals)) / tokenPriceInUSD;
            // (1e8 USD) * (10^tokenDecimals) / (1e8 USD) → tokenDecimals precision

            return tokenAmount; // Correct token amount (in token's own decimals)
        }
    }

    /**
     * @notice Retrieves current price data for a token and ETH
     * @dev Fetches latest price data from Chainlink price feeds
     * @param token Address of the token to get price information for
     * @return Array containing [tokenPriceInUSD, tokenDecimals, ethPriceInUSD, ethDecimals]
     * @custom:requirements
     * - Token price feed must be configured
     * - ETH price feed must be configured
     * - Price feed answers must be positive
     * @custom:reverts
     * - "Invalid token price" if token price <= 0
     * - "Invalid ETH price" if ETH price <= 0
     */
    function getTokenAmount(address token) public view returns (uint256[] memory) {
        AggregatorV3Interface priceFeed = AggregatorV3Interface(tokenPriceFeed[token]);
        (
            ,
            int256 answer,
            ,
            ,
        ) = priceFeed.latestRoundData();
        require(answer != 0, "Invalid token price");
        uint256 tokenPriceInUSD = uint256(answer);
        uint8 decimals = priceFeed.decimals();

        AggregatorV3Interface ethPriceAggregator = AggregatorV3Interface(ethPriceFeed);
        (
            ,
            int256 ethAnswer,
            ,
            ,
        ) = ethPriceAggregator.latestRoundData();
        require(ethAnswer != 0, "Invalid ETH price");
        uint256 ethPriceInUSD = uint256(ethAnswer);
        uint8 ethDecimals = ethPriceAggregator.decimals();

        uint256[] memory result = new uint256[](4);
        result[0] = tokenPriceInUSD;
        result[1] = decimals;
        result[2] = ethPriceInUSD;
        result[3] = ethDecimals;

        return result;
    }

    /**
     * @notice Computes the keccak256 hash of given data
     * @dev Pure function for generating message hashes
     * @param _data Bytes data to hash
     * @return The keccak256 hash of the input data
     */
    function getMessageHash(bytes memory _data) public pure returns (bytes32) {
        return keccak256(_data);
    }

    /**
     * @notice Creates an Ethereum signed message hash
     * @dev Prepends Ethereum message prefix to the hash
     * @param _messageHash The original message hash
     * @return The hash with Ethereum signed message prefix
     */
    function getEthSignedMessageHash(bytes32 _messageHash) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(PREFIX, _messageHash));
    }

    /**
     * @notice Recovers the signer address from an Ethereum signed message hash and signature
     * @dev Uses ecrecover to extract the signer from the signature components
     * @param hash The hash of the signed message with Ethereum prefix
     * @param _signature The signature bytes (65 bytes: r + s + v)
     * @return The address of the account that signed the message
     * @custom:requirements
     * - Signature must be exactly 65 bytes
     * - Signature 'v' value must be 27 or 28
     * @custom:reverts
     * - "Invalid signature length" if signature is not 65 bytes
     * - "Invalid signature 'v' value" if v is not 27 or 28
     */
    function recoverSigner(bytes32 hash, bytes memory _signature) public pure returns (address) {
        require(_signature.length == 65, "Invalid signature length");
        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }

        // Enforce EIP-2: Prevent signature malleability by requiring low s-values
        require(
            uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0,
            "Invalid signature 's' value"
        );

        // Check v-value is correct
        require(v == 27 || v == 28, "Invalid signature 'v' value");

        return ecrecover(hash, v, r, s);
    }

    /// @notice EIP-712 domain separator type hash constant
    bytes32 public constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );

    /// @notice Mapping to track nonces for each address to prevent replay attacks
    mapping(address => uint256) public nonces;

    /**
     * @notice Structure containing signature verification parameters
     * @param nonce Current nonce for the signer to prevent replay attacks
     * @param deadline Timestamp after which the signature expires
     * @param chainId Chain ID to prevent cross-chain signature reuse
     * @param contractAddress Contract address to prevent cross-contract signature reuse
     * @param domainSeparator EIP-712 domain separator for structured data signing
     */
    struct SignatureParams {
        uint256 nonce;
        uint256 deadline;
        uint256 chainId;
        address contractAddress;
        bytes32 domainSeparator;
    }

    /**
     * @notice Verifies a signature using secure EIP-712 structured data signing
     * @dev Implements comprehensive security checks including nonce tracking, deadline verification, and chain validation
     * @param data The data that was signed
     * @param params Signature verification parameters including nonce, deadline, chain ID, and domain separator
     * @param signer Expected signer address
     * @param signature The signature to verify
     * @return True if signature is valid, false otherwise
     * @custom:requirements
     * - Signature must not be expired (deadline check)
     * - Must be called on correct chain (chain ID check)
     * - Nonce must match expected value for signer
     * @custom:security
     * - Automatically increments nonce to prevent replay attacks
     * - Uses EIP-712 structured data to prevent signature malleability
     * - Validates chain ID to prevent cross-chain attacks
     * @custom:reverts
     * - "Signature expired" if current time > deadline
     * - "Wrong chain" if chain ID doesn't match
     * - "Invalid nonce" if nonce doesn't match expected value
     */
    function verifySignatureSecure(
        bytes memory data,
        SignatureParams memory params,
        address signer,
        bytes memory signature
    ) public returns (bool) {
        // Check deadline
        require(block.timestamp <= params.deadline, "Signature expired");

        // Check chain
        require(block.chainid == params.chainId, "Wrong chain");

        // Check and update nonce
        require(nonces[signer] == params.nonce, "Invalid nonce");
        nonces[signer]++;

        // Build structured message
        bytes32 messageHash = keccak256(abi.encode(
            keccak256("UnifiedIDOperation(bytes data,uint256 nonce,uint256 deadline,uint256 chainId,address contractAddress)"),
            keccak256(data),
            params.nonce,
            params.deadline,
            params.chainId,
            params.contractAddress
        ));

        // EIP-712 style hash
        bytes32 digest = keccak256(abi.encodePacked(
            "\x19\x01",
            params.domainSeparator,
            messageHash
        ));

        return recoverSigner(digest, signature) == signer;
    }

    /**
     * @notice Returns the current nonce for a given signer address
     * @dev Used to get the next nonce value for signature creation
     * @param signer Address to get nonce for
     * @return Current nonce value for the signer
     */
    function getCurrentNonce(address signer) external view returns (uint256) {
        return nonces[signer];
    }

    /**
     * @notice Creates an EIP-712 domain separator for structured data signing
     * @dev Pure function to generate domain separator for any contract
     * @param name The name of the signing domain
     * @param version The version of the signing domain
     * @param chainId The chain ID for domain separation
     * @param verifyingContract The contract address for domain separation
     * @return The computed domain separator hash
     */
    function createDomainSeparator(
        string memory name,
        string memory version,
        uint256 chainId,
        address verifyingContract
    ) public pure returns (bytes32) {
        return keccak256(abi.encode(
            DOMAIN_TYPEHASH,
            keccak256(bytes(name)),
            keccak256(bytes(version)),
            chainId,
            verifyingContract
        ));
    }

    /**
     * @notice Legacy signature verification function (deprecated)
     * @dev Kept for backward compatibility but use verifySignatureSecure() for new implementations
     * @param _data The data that was signed
     * @param _expectedSigner Expected signer address
     * @param _signature The signature to verify
     * @return True if signature is valid
     * @custom:deprecated Use verifySignatureSecure() instead for enhanced security
     */
    function verifySignature(
        bytes memory _data,
        address _expectedSigner,
        bytes memory _signature
    ) public pure returns (bool) {
        bytes32 messageHash = getMessageHash(_data);
        bytes32 ethSignedMessageHash = getEthSignedMessageHash(messageHash);
        address signer = recoverSigner(ethSignedMessageHash, _signature);
        return signer == _expectedSigner;
    }

    /// @notice Deprecated constant: Maximum allowed unified ID length
    uint8 constant MAX_UNIFIED_ID_LENGTH = 16;

    /// @notice Deprecated constant: Minimum required unified ID length
    uint8 constant MIN_UNIFIED_ID_LENGTH = 4;

    /**
     * @notice Checks if an address is a contract or externally owned account
     * @dev Uses extcodesize to determine if address contains contract code
     * @param _resolverAddress Address to check
     * @return True if address is a contract, false if EOA
     */
    function isContract(address _resolverAddress)
    public view
    returns(bool)
    {
        uint32 size;
        assembly {
            size := extcodesize(_resolverAddress)
        }
        return (size != 0);
    }

    /**
     * @notice Converts a string to lowercase
     * @dev Iterates through each character and converts uppercase to lowercase
     * @param str String to be converted
     * @return Lowercase version of the input string
     */
    function toLower(string memory str) public pure returns (string memory) {
        bytes memory bStr = bytes(str);
        bytes memory bLower = new bytes(bStr.length);
        for (uint256 i = 0; i < bStr.length; ++i) {
            // Uppercase character...
            if ((uint8(bStr[i]) >= 65) && (uint8(bStr[i]) <= 90)) {
                // So we add 32 to make it lowercase
                bLower[i] = bytes1(uint8(bStr[i]) + 32);
            } else {
                bLower[i] = bStr[i];
            }
        }
        return string(bLower);
    }

    /**
     * @notice Checks the length of a string
     * @dev Returns the byte length of the string
     * @param _name String to check length of
     * @return Length of the string in bytes
     * @custom:reverts "Library : String passed is of zero length" if string is empty
     */
    function checkLength(string memory _name) public pure returns (uint8){
        require(bytes(_name).length != 0, "Library : String passed is of zero length");
        return uint8(bytes(_name).length);
    }

    /**
     * @notice Validates if string contains only alphanumeric and ASCII printable characters
     * @dev Checks each character to ensure it's within allowed ranges
     * @param unifiedId String to validate
     * @return True if all characters are valid, false otherwise
     * @custom:allowed-chars
     * - Digits: 0-9 (0x30-0x39)
     * - Lowercase: a-z (0x61-0x7A)
     * - Uppercase: A-Z (0x41-0x5A)
     * - ASCII printable: 32-126
     */
    function checkAlphaNumericAndAscii(string memory unifiedId) public pure returns (bool) {
        bytes memory b = bytes(unifiedId);

        for(uint256 i; i < b.length; ++i) {
            bytes1 char = b[i];

            if(!(
                (char >= 0x30 && char <= 0x39) || // 0-9
                (char >= 0x61 && char <= 0x7A) || // a-z
                (char >= 0x41 && char <= 0x5A) || // A-Z
                (uint8(char) >= 32 && uint8(char) <= 126) // ASCII printable characters
            )) {
                return false;
            }
        }

        return true;
    }

    /**
     * @notice Validates a unified ID format and length
     * @dev Checks if unified ID meets all requirements: length, character set, etc.
     * @param _registrarName Unified ID to validate
     * @return True if valid
     * @custom:requirements
     * - Must be within configured length limits
     * - Must contain only alphanumeric and ASCII printable characters
     * @custom:reverts
     * - "only alphanumeric allowed" if invalid characters found
     * - "Unified Id length out of bounds" if length is invalid
     */
    function unifiedIdValid(string memory _registrarName) public view returns (bool) {
        string memory nameInLowerCase = toLower(_registrarName);
        uint8 length = checkLength(_registrarName);
        require(checkAlphaNumericAndAscii(nameInLowerCase), "only alphanumeric allowed");
        require(length <= maxUnifiedIdLength && length >= minUnifiedIdLength, "Unified Id length out of bounds");
        return true;
    }

    /**
     * @notice Check if unified ID is valid (alias for backward compatibility)
     * @dev Calls unifiedIdValid() internally
     * @param _unifiedId unified ID to validate
     * @return True if valid
     */
    function isUnifiedIdValid(string memory _unifiedId) public view returns (bool) {
        return unifiedIdValid(_unifiedId);
    }

    // ==================== ROLE MANAGEMENT FUNCTIONS ====================

    /**
     * @notice Grant admin role to an address
     * @param admin Address to grant admin role
     */
    function grantAdminRole(address admin) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(ADMIN_ROLE, admin);
    }

    /**
     * @notice Revoke admin role from an address
     * @param admin Address to revoke admin role
     */
    function revokeAdminRole(address admin) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(ADMIN_ROLE, admin);
    }

    /**
     * @notice Grant price feed manager role to an address
     * @param manager Address to grant price feed manager role
     */
    function grantPriceFeedManagerRole(address manager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(PRICE_FEED_MANAGER_ROLE, manager);
    }

    /**
     * @notice Revoke price feed manager role from an address
     * @param manager Address to revoke price feed manager role
     */
    function revokePriceFeedManagerRole(address manager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(PRICE_FEED_MANAGER_ROLE, manager);
    }

    /**
     * @notice Grant config manager role to an address
     * @param manager Address to grant config manager role
     */
    function grantConfigManagerRole(address manager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(CONFIG_MANAGER_ROLE, manager);
    }

    /**
     * @notice Revoke config manager role from an address
     * @param manager Address to revoke config manager role
     */
    function revokeConfigManagerRole(address manager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(CONFIG_MANAGER_ROLE, manager);
    }

    /**
     * @notice Check if address has admin role
     * @param account Address to check
     * @return True if address has admin role
     */
    function isAdmin(address account) external view returns (bool) {
        return hasRole(ADMIN_ROLE, account);
    }

    /**
     * @notice Check if address has price feed manager role
     * @param account Address to check
     * @return True if address has price feed manager role
     */
    function isPriceFeedManager(address account) external view returns (bool) {
        return hasRole(PRICE_FEED_MANAGER_ROLE, account);
    }

    /**
     * @notice Check if address has config manager role
     * @param account Address to check
     * @return True if address has config manager role
     */
    function isConfigManager(address account) external view returns (bool) {
        return hasRole(CONFIG_MANAGER_ROLE, account);
    }

    // === ADMIN FUNCTIONS ===

    /**
     * @notice Sets the length limits for unified IDs
     * @dev Updates both minimum and maximum length requirements
     * @param _minLength Minimum allowed length for unified IDs
     * @param _maxLength Maximum allowed length for unified IDs
     * @custom:requirements
     * - Only config manager can call this function
     * - _minLength must be greater than 0
     * - _maxLength must be greater than _minLength
     * @custom:events Emits UnifiedIdLengthLimitsUpdated
     */
    function setUnifiedIdLengthLimits(uint8 _minLength, uint8 _maxLength) external onlyRole(CONFIG_MANAGER_ROLE) {
        require(_minLength != 0 && _maxLength > _minLength, "Invalid length limits");
        minUnifiedIdLength = _minLength;
        maxUnifiedIdLength = _maxLength;
        emit UnifiedIdLengthLimitsUpdated(_minLength, _maxLength);
    }

    /**
     * @notice Returns current contract configuration
     * @dev Provides read access to key configuration parameters
     * @return _minUnifiedIdLength Current minimum unified ID length
     * @return _maxUnifiedIdIdLength Current maximum unified ID length
     * @return currentOwner Current contract owner address
     */
    function getConfiguration() external view returns (
        uint8 _minUnifiedIdLength,
        uint8 _maxUnifiedIdIdLength,
        address currentOwner
    ) {
        return (
            minUnifiedIdLength,
            maxUnifiedIdLength,
            owner()
        );
    }

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[49] private __gap;
}

